def scalar(s):
    s = s.strip()
    if s.startswith("[") and s.endswith("]"):
        inner = s[1:-1].strip()
        return [] if not inner else [x.strip() for x in inner.split(",")]
    if s in ("true", "false"):
        return s == "true"
    return s


def parse_yaml(text):
    lines = []
    for raw in text.splitlines():
        if not raw.strip() or raw.strip().startswith("#"):
            continue
        lines.append((len(raw) - len(raw.lstrip(" ")), raw.strip()))
    pos = [0]

    def mapping(indent):
        d = {}
        while pos[0] < len(lines):
            ind, content = lines[pos[0]]
            if ind != indent or content.startswith("- "):
                break
            pos[0] += 1
            k, _, v = content.partition(":")
            k, v = k.strip(), v.strip()
            if v == "":
                if pos[0] < len(lines) and lines[pos[0]][0] > indent:
                    d[k] = block(lines[pos[0]][0])
                else:
                    d[k] = None
            else:
                d[k] = scalar(v)
        return d

    def block(indent):
        if lines[pos[0]][1].startswith("- "):
            items = []
            while pos[0] < len(lines) and lines[pos[0]][0] == indent and lines[pos[0]][1].startswith("- "):
                rest = lines[pos[0]][1][2:].strip()
                pos[0] += 1
                if ":" in rest:
                    k, _, v = rest.partition(":")
                    d = {k.strip(): scalar(v)}
                    while pos[0] < len(lines) and lines[pos[0]][0] > indent:
                        d.update(mapping(lines[pos[0]][0]))
                    items.append(d)
                else:
                    items.append(scalar(rest))
            return items
        return mapping(indent)

    return block(lines[0][0])


def topo(graph):
    indeg = {n: 0 for n in graph}
    for n, deps in graph.items():
        for d in deps:
            if d in indeg:
                indeg[n] += 1
    ready = sorted(n for n in indeg if indeg[n] == 0)
    order = []
    while ready:
        n = ready.pop(0)
        order.append(n)
        for m, deps in graph.items():
            if n in deps:
                indeg[m] -= 1
                if indeg[m] == 0:
                    ready.append(m)
        ready.sort()
    if len(order) != len(graph):
        # 找环
        remaining = [n for n in graph if n not in order]
        path, cur = [], min(remaining)
        while cur not in path:
            path.append(cur)
            nxt = [d for d in graph[cur] if d not in order]
            cur = min(nxt) if nxt else min(remaining)
        return order, path[path.index(cur):] + [cur]
    return order, None


def validate(text):
    issues = []
    if "\t" in text:
        issues.append("tab_indentation")
    doc = parse_yaml(text)
    if not isinstance(doc, dict):
        return ["not_a_mapping"], None
    if "on" not in doc:
        issues.append("missing_trigger")
    jobs = doc.get("jobs")
    if not isinstance(jobs, dict) or not jobs:
        return issues + ["missing_jobs"], None
    graph = {}
    for jn, job in jobs.items():
        if not isinstance(job, dict):
            issues.append("job_not_mapping:" + jn)
            graph[jn] = []
            continue
        if "runs-on" not in job:
            issues.append("missing_runs_on:" + jn)
        steps = job.get("steps")
        if not isinstance(steps, list) or not steps:
            issues.append("missing_steps:" + jn)
        else:
            for si, st in enumerate(steps):
                if not isinstance(st, dict) or not ("run" in st or "uses" in st):
                    issues.append("bad_step:%s#%d" % (jn, si))
        needs = job.get("needs") or []
        if isinstance(needs, str):
            needs = [needs]
        graph[jn] = list(needs)
    for jn, deps in graph.items():
        for d in deps:
            if d not in jobs:
                issues.append("unknown_needs:%s>%s" % (jn, d))
    order, cycle = topo({k: [d for d in v if d in jobs] for k, v in graph.items()})
    if cycle:
        issues.append("cycle:" + "->".join(cycle))
    return issues, order


for label, text in (("good", GOOD), ("bad", BAD)):
    issues, order = validate(text)
    print("=== workflow(%s) ===" % label)
